"use client"

import {
  flexRender,
  getCoreRowModel,
  getFacetedRowModel,
  getFacetedUniqueValues,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  type ColumnDef,
  type ColumnFiltersState,
  type Row,
  type SortingState,
  type VisibilityState,
  useReactTable,
} from "@tanstack/react-table"
import * as React from "react"

import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { cn } from "@/lib/utils"
import { DataTablePagination } from "./data-table-pagination"
import { DataTableToolbar } from "./data-table-toolbar"
import type { FilterDef } from "./filters"
import type { SearchFilter, TableActions, TableMultiRowAction } from "./data-table.types"

export type DataTableProps<TData, TValue> = {
  columns: ColumnDef<TData, TValue>[]
  data: TData[]
  multiRowActions?: TableMultiRowAction<TData>[]
  searchFilter?: SearchFilter
  filtersDef?: FilterDef[]
  resetFilters?: () => void
  tableActions?: TableActions
  className?: string
  tableRowClassName?: string | ((row: TData) => string)
  tableCellClassName?: string
  rowLinkClassName?: string
  onRowClick?: (row: Row<TData>) => void
  onRowLinkClick?: (row: Row<TData>) => string
  hidePagination?: boolean
  isFetching?: boolean
}

export function DataTable<TData, TValue>({
  columns,
  data,
  multiRowActions,
  searchFilter,
  filtersDef,
  resetFilters,
  tableActions,
  tableRowClassName,
  tableCellClassName,
  rowLinkClassName,
  hidePagination = false,
  onRowClick,
  onRowLinkClick,
  isFetching = false,
  className,
}: DataTableProps<TData, TValue>) {
  const [rowSelection, setRowSelection] = React.useState({})
  const [columnVisibility, setColumnVisibility] = React.useState<VisibilityState>({})
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>([])
  const [sorting, setSorting] = React.useState<SortingState>([])

  const table = useReactTable({
    data,
    columns,
    state: {
      sorting,
      columnVisibility,
      rowSelection,
      columnFilters,
    },
    enableRowSelection: true,
    onRowSelectionChange: setRowSelection,
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    onColumnVisibilityChange: setColumnVisibility,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFacetedRowModel: getFacetedRowModel(),
    getFacetedUniqueValues: getFacetedUniqueValues(),
  })

  const getRowClassName = (row: TData) =>
    typeof tableRowClassName === "function" ? tableRowClassName(row) : tableRowClassName

  return (
    <div className="relative flex flex-col gap-4" aria-busy={isFetching}>
      <DataTableToolbar
        table={table}
        searchFilter={searchFilter}
        filtersDef={filtersDef}
        resetFilters={resetFilters}
        multiRowActions={multiRowActions}
        tableActions={tableActions}
      />
      <div
        className={cn(
          "relative min-h-[calc(80vh-120px)] max-h-[calc(80vh-220px)] overflow-y-auto rounded-md border md:max-h-[calc(80dvh-200px)]",
          className,
        )}
      >
        {isFetching && (
          <div
            aria-hidden="true"
            className="absolute inset-x-0 top-0 z-10 h-0.5 animate-pulse bg-primary"
          />
        )}
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <TableHead key={header.id} colSpan={header.colSpan}>
                    {header.isPlaceholder
                      ? null
                      : flexRender(header.column.columnDef.header, header.getContext())}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.length > 0 ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && "selected"}
                  className={cn(
                    onRowClick || onRowLinkClick ? "cursor-pointer" : undefined,
                    getRowClassName(row.original),
                  )}
                  onClick={onRowClick ? () => onRowClick(row) : undefined}
                >
                  {row.getVisibleCells().map((cell) => {
                    const linkHref = onRowLinkClick?.(row)
                    const content = flexRender(cell.column.columnDef.cell, cell.getContext())

                    return (
                      <TableCell key={cell.id} className={cn("py-2", tableCellClassName)}>
                        {linkHref ? (
                          <a
                            href={linkHref}
                            className={cn("flex h-full w-full items-center", rowLinkClassName)}
                            onClick={(event) => event.stopPropagation()}
                          >
                            {content}
                          </a>
                        ) : (
                          content
                        )}
                      </TableCell>
                    )
                  })}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={columns.length} className="h-24 text-center">
                  No results.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      {!hidePagination && <DataTablePagination table={table} />}
    </div>
  )
}

export type { SearchFilter, TableMultiRowAction, TableRowAction } from "./data-table.types"
export type { TableActions, TableAction, TableActionsOptions } from "./data-table.types"

"use client"

import {
  flexRender,
  getCoreRowModel,
  getFacetedRowModel,
  getFacetedUniqueValues,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  type ColumnDef,
  type ColumnFiltersState,
  type Row,
  type SortingState,
  type Updater,
  type VisibilityState,
  useReactTable,
} from "@tanstack/react-table"
import * as React from "react"

import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { cn } from "@/lib/utils"
import { DataTablePagination } from "./data-table-pagination"
import { DataTableToolbar } from "./data-table-toolbar"
import type { DataTableProps } from "./data-table"
import type { TableActions, TableMultiRowAction } from "./data-table.types"
import { formatTableFilters } from "./data-table-utils"
import type { FilterDef } from "./filters"

export type PaginatedData<TData> = {
  results: TData[]
  count: number
  page_size: number
}

export type Pagination = {
  page: number
  page_size: number
  setPage: (value: number) => void
  setPageSize: (value: number) => void
  query: string
}

export type TableActionsProps = TableActions

export type PaginatedDataTableProps<TData, TValue> = Omit<DataTableProps<TData, TValue>, "data"> & {
  paginatedData: PaginatedData<TData>
  pagination?: Pagination
  filtersDef?: FilterDef[]
  resetFilters?: () => void
  onFilterChange?: (filters: Record<string, unknown>) => void
  isLoading?: boolean
  isFetching?: boolean
  multiRowActions?: TableMultiRowAction<TData>[]
  tableActions?: TableActions
  displayPaginationUI?: boolean
}

export function PaginatedDataTable<TData, TValue>({
  columns,
  searchFilter,
  filtersDef,
  resetFilters,
  paginatedData,
  pagination,
  multiRowActions,
  className,
  tableRowClassName,
  tableCellClassName,
  rowLinkClassName,
  onRowClick,
  onRowLinkClick,
  onFilterChange,
  isLoading = false,
  isFetching = false,
  tableActions,
  displayPaginationUI = true,
}: PaginatedDataTableProps<TData, TValue>) {
  const [rowSelection, setRowSelection] = React.useState({})
  const [columnVisibility, setColumnVisibility] = React.useState<VisibilityState>({})
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>([])
  const [sorting, setSorting] = React.useState<SortingState>([])
  const scrollContainerRef = React.useRef<HTMLDivElement>(null)
  const savedScrollTop = React.useRef(0)

  React.useEffect(() => {
    const container = scrollContainerRef.current
    if (!container) return

    const handleScroll = () => {
      savedScrollTop.current = container.scrollTop
    }

    container.addEventListener("scroll", handleScroll, { passive: true })
    return () => container.removeEventListener("scroll", handleScroll)
  }, [])

  React.useLayoutEffect(() => {
    savedScrollTop.current = 0
  }, [pagination?.page, pagination?.page_size])

  React.useLayoutEffect(() => {
    const container = scrollContainerRef.current
    if (!container || isLoading) return
    container.scrollTop = savedScrollTop.current
  }, [isLoading, paginatedData])

  const pageCount = Math.max(
    1,
    Math.ceil(paginatedData.count / Math.max(1, paginatedData.page_size)),
  )

  const table = useReactTable({
    data: paginatedData.results,
    columns,
    pageCount,
    manualPagination: Boolean(pagination),
    state: {
      sorting,
      columnVisibility,
      rowSelection,
      columnFilters,
      ...(pagination
        ? {
            pagination: {
              pageIndex: pagination.page - 1,
              pageSize: pagination.page_size,
            },
          }
        : {}),
    },
    enableRowSelection: true,
    onRowSelectionChange: setRowSelection,
    onSortingChange: setSorting,
    onColumnFiltersChange: (updater: Updater<ColumnFiltersState>) => {
      const nextFilters = typeof updater === "function" ? updater(columnFilters) : updater
      setColumnFilters(nextFilters)
      onFilterChange?.(formatTableFilters(nextFilters))
    },
    onColumnVisibilityChange: setColumnVisibility,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFacetedRowModel: getFacetedRowModel(),
    getFacetedUniqueValues: getFacetedUniqueValues(),
    onPaginationChange: (updater) => {
      if (!pagination) return

      const currentPagination = table.getState().pagination
      const nextPagination =
        typeof updater === "function" ? updater(currentPagination) : updater

      pagination.setPage(nextPagination.pageIndex + 1)
      pagination.setPageSize(nextPagination.pageSize)
    },
  })

  const getRowClassName = (row: TData) =>
    typeof tableRowClassName === "function" ? tableRowClassName(row) : tableRowClassName

  return (
    <div className={cn("relative flex flex-col gap-4", className)} aria-busy={isLoading || isFetching}>
      <DataTableToolbar
        table={table}
        searchFilter={searchFilter}
        filtersDef={filtersDef}
        resetFilters={resetFilters}
        multiRowActions={multiRowActions}
        tableActions={tableActions}
      />
      <div className="relative">
        {isLoading && (
          <div className="absolute inset-0 z-10 flex items-center justify-center bg-background/50">
            <span
              role="status"
              aria-label="Loading"
              className="size-6 animate-spin rounded-full border-2 border-primary border-t-transparent"
            />
          </div>
        )}
        {isFetching && (
          <div
            aria-hidden="true"
            className="absolute inset-x-0 top-0 z-10 h-0.5 animate-pulse bg-primary"
          />
        )}
        <div
          ref={scrollContainerRef}
          className="relative max-h-[calc(80vh-220px)] min-h-[400px] overflow-x-auto overflow-y-auto rounded-md border md:max-h-[calc(80dvh-200px)]"
        >
          <div className="relative min-w-full w-fit">
            <Table>
              <TableHeader>
                {table.getHeaderGroups().map((headerGroup) => (
                  <TableRow key={headerGroup.id}>
                    {headerGroup.headers.map((header) => (
                      <TableHead key={header.id} colSpan={header.colSpan}>
                        {header.isPlaceholder
                          ? null
                          : flexRender(header.column.columnDef.header, header.getContext())}
                      </TableHead>
                    ))}
                  </TableRow>
                ))}
              </TableHeader>
              <TableBody>
                {table.getRowModel().rows.length > 0
                  ? table.getRowModel().rows.map((row) => (
                      <TableRow
                        key={row.id}
                        data-state={row.getIsSelected() && "selected"}
                        className={cn(
                          onRowClick || onRowLinkClick ? "cursor-pointer" : undefined,
                          getRowClassName(row.original),
                        )}
                        onClick={onRowClick ? () => onRowClick(row) : undefined}
                      >
                        {row.getVisibleCells().map((cell) => {
                          const linkHref = onRowLinkClick?.(row)
                          const content = flexRender(cell.column.columnDef.cell, cell.getContext())

                          return (
                            <TableCell
                              key={cell.id}
                              className={cn(
                                onRowLinkClick ? "p-0" : "py-2",
                                tableCellClassName,
                              )}
                            >
                              {linkHref ? (
                                <a
                                  href={linkHref}
                                  className={cn("flex h-full w-full items-center px-2 py-2", rowLinkClassName)}
                                  onClick={(event) => event.stopPropagation()}
                                >
                                  {content}
                                </a>
                              ) : (
                                content
                              )}
                            </TableCell>
                          )
                        })}
                      </TableRow>
                    ))
                  : !isLoading && (
                      <TableRow>
                        <TableCell colSpan={columns.length} className="h-24 text-center">
                          No results.
                        </TableCell>
                      </TableRow>
                    )}
              </TableBody>
            </Table>
          </div>
        </div>
      </div>
      {!isLoading && displayPaginationUI && pagination && <DataTablePagination table={table} />}
    </div>
  )
}

export type { TableAction, TableActions, TableActionsOptions, TableMultiRowAction } from "./data-table.types"
export type { DataTableProps } from "./data-table"

import type { Row } from "@tanstack/react-table"
import type { ComponentType } from "react"

export type SearchFilter = {
  accessorKey: string
  placeholder?: string
  onChangeHandler?: (value: string) => void
}

export type TableRowAction<TData> = {
  label: string
  clickHandler: (row: Row<TData>) => void | Promise<void>
  Icon?: ComponentType<{ className?: string }>
  hide?: boolean | ((args: { row: Row<TData> }) => boolean)
  /** @deprecated Use `hide` instead. */
  notAllowed?: boolean | ((args: { row: Row<TData> }) => boolean)
  hidden?: boolean | ((args: { row: Row<TData> }) => boolean)
}

export type TableMultiRowAction<TData> = {
  label: string
  clickHandler: (rows: Row<TData>[]) => void | Promise<void>
  Icon?: ComponentType<{ className?: string }>
  hide?: boolean
  /** @deprecated Use `hide` instead. */
  notAllowed?: boolean
}

export type TableAction = {
  label: string
  handler?: () => void | Promise<void>
  icon?: ComponentType<{ className?: string }>
  hidden?: boolean
  className?: string
}

export type TableActionsOptions = {
  label?: string
  icon?: ComponentType<{ className?: string }>
  style?: "dropdown" | "inline"
}

export type TableActions = {
  options?: TableActionsOptions
  actions: TableAction[]
}

import type { ColumnFiltersState } from "@tanstack/react-table"
import { useCallback, useEffect, useRef } from "react"

export function formatTableFilters(filters: ColumnFiltersState): Record<string, unknown> {
  return filters.reduce<Record<string, unknown>>((result, filter) => {
    result[filter.id] = String(filter.value)
    return result
  }, {})
}

type DebouncedCallback<Args extends unknown[]> = (...args: Args) => void

export function useDebouncedCallback<Args extends unknown[]>(
  callback: DebouncedCallback<Args>,
  delay: number,
) {
  const callbackRef = useRef(callback)
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)

  useEffect(() => {
    callbackRef.current = callback
  }, [callback])

  useEffect(() => {
    return () => {
      clearTimeout(timeoutRef.current)
    }
  }, [])

  return useCallback(
    (...args: Args) => {
      clearTimeout(timeoutRef.current)
      timeoutRef.current = setTimeout(() => callbackRef.current(...args), Math.max(0, delay))
    },
    [delay],
  )
}

"use client"

import type { Table } from "@tanstack/react-table"
import { Menu, X } from "lucide-react"
import * as React from "react"
import type { DateRange } from "react-day-picker"

import { CalendarDatePicker } from "@/components/ui/calendar-date-picker"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { DataTableFacetedFilter } from "./data-table-faceted-filter"
import { DataTableMultiRowActions } from "./data-table-multi-row-actions"
import { InputFilter } from "./data-table-filters"
import { DataTableViewOptions } from "./data-table-view-options"
import type {
  SearchFilter,
  TableAction,
  TableActions,
  TableMultiRowAction,
} from "./data-table.types"
import { useDebouncedCallback } from "./data-table-utils"
import type { FilterDef } from "./filters"

export type MultiSelectFilter = {
  accessorKey: string
  title: string
  options: {
    label: string
    value: string
    Icon?: React.ComponentType<{ className?: string }>
  }[]
}

export type filterElementsType = {
  searchInput?: SearchFilter
  multiSelectFilters?: MultiSelectFilter[]
}

type DataTableToolbarProps<TData> = {
  table: Table<TData>
  searchFilter?: SearchFilter
  multiRowActions?: TableMultiRowAction<TData>[]
  filtersDef?: FilterDef[]
  resetFilters?: () => void
  tableActions?: TableActions
}

const EMPTY_FILTERS_DEF: FilterDef[] = []

function isFilterHidden(filter: FilterDef) {
  const hide = filter.hide ?? filter.notAllowed
  return typeof hide === "function" ? hide() : hide
}

function TableActionsMenu({ tableActions }: { tableActions: TableActions }) {
  const [pendingIndex, setPendingIndex] = React.useState<number | null>(null)
  const visibleActions = tableActions.actions.filter((action) => !action.hidden)
  const style = tableActions.options?.style ?? "dropdown"
  const label = tableActions.options?.label ?? "Actions"
  const TriggerIcon = tableActions.options?.icon ?? Menu

  if (visibleActions.length === 0) return null

  async function runAction(index: number, action: TableAction) {
    if (!action.handler) return

    setPendingIndex(index)
    try {
      await action.handler()
    } finally {
      setPendingIndex(null)
    }
  }

  if (style === "inline") {
    return (
      <div className="flex items-center gap-2">
        {visibleActions.map((action, index) => {
          const ActionIcon = action.icon
          const isPending = pendingIndex === index
          return (
            <Button
              key={action.label}
              variant="outline"
              className={action.className}
              disabled={pendingIndex !== null}
              onClick={() => {
                void runAction(index, action)
              }}
            >
              {isPending ? (
                <span className="size-4 animate-spin rounded-full border-2 border-current border-t-transparent" />
              ) : (
                ActionIcon && <ActionIcon className="size-4" />
              )}
              {!isPending && action.label}
            </Button>
          )
        })}
      </div>
    )
  }

  return (
    <DropdownMenu modal={false}>
      <DropdownMenuTrigger asChild disabled={pendingIndex !== null}>
        <Button variant="outline" size="sm" className="h-8">
          {pendingIndex !== null ? (
            <span className="size-4 animate-spin rounded-full border-2 border-current border-t-transparent" />
          ) : (
            <TriggerIcon className="size-4" />
          )}
          {pendingIndex === null && label}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        {visibleActions.map((action, index) => {
          const ActionIcon = action.icon
          return (
            <DropdownMenuItem
              key={action.label}
              className={action.className}
              onSelect={() => {
                void runAction(index, action)
              }}
            >
              {ActionIcon && <ActionIcon className="size-4" />}
              {action.label}
            </DropdownMenuItem>
          )
        })}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

function SelectFilter<TData>({ table, filter }: { table: Table<TData>; filter: FilterDef }) {
  const updateValue = React.useCallback(
    (value: string | null) => {
      if (filter.onChange) {
        filter.onChange(value)
        return
      }

      table.getColumn(filter.accessorKey)?.setFilterValue(value ?? undefined)
    },
    [filter, table],
  )
  const debouncedUpdate = useDebouncedCallback(updateValue, filter.debounce ?? 1000)
  const onChange = filter.onChange ? debouncedUpdate : updateValue
  const value = filter.onChange
    ? filter.defaultValue ?? null
    : ((table.getColumn(filter.accessorKey)?.getFilterValue() as string | undefined) ?? null)

  return (
    <DataTableFacetedFilter
      title={filter.title}
      options={filter.options ?? []}
      value={value}
      onChange={onChange}
    />
  )
}

function DateFilter({
  filter,
  defaultsRef,
  today,
}: {
  filter: FilterDef
  defaultsRef: React.MutableRefObject<Record<string, DateRange>>
  today: Date
}) {
  if (filter.numberOfMonths === 1 && !defaultsRef.current[filter.accessorKey]) {
    defaultsRef.current[filter.accessorKey] =
      filter.defaultDateRange ??
      (filter.defaultToCurrentMonthYear ? { from: today, to: today } : {})
  }

  const date =
    (filter.numberOfMonths === 1
      ? defaultsRef.current[filter.accessorKey]
      : filter.defaultDateRange ??
        (filter.defaultToCurrentMonthYear ? { from: today, to: today } : {})) ?? {}
  return (
    <CalendarDatePicker
      suppressHydrationWarning
      date={date}
      variant="outline"
      onDateSelect={(range) => filter.onDateSelectChange?.(range)}
      placeholder={filter.placeHolder}
      enableWheel={false}
      className="w-full truncate px-2 md:text-xs"
      numberOfMonths={filter.numberOfMonths ?? 2}
      yearsRange={filter.yearsRange}
      yearsOrder={filter.yearsOrder}
      minYear={filter.minYear}
      maxYear={filter.maxYear}
      preventFuture={filter.preventFuture}
      classNames={
        filter.classNames ?? {
          caption_label: "hidden",
          nav_button: "hidden",
        }
      }
    />
  )
}

export function DataTableToolbar<TData>({
  table,
  searchFilter,
  multiRowActions,
  filtersDef = EMPTY_FILTERS_DEF,
  tableActions,
}: DataTableToolbarProps<TData>) {
  const dateDefaultsRef = React.useRef<Record<string, DateRange>>({})
  const today = React.useMemo(() => new Date(), [])
  const isTableFiltered = table.getState().columnFilters.length > 0
  const hasDefaultFilters = filtersDef.some(
    (filter) => filter.defaultDateRange?.from || filter.defaultDateRange?.to || filter.defaultValue,
  )
  const resolvedMultiRowActions = multiRowActions ?? []

  return (
    <div className="flex flex-col-reverse items-start justify-between gap-4 lg:flex-row">
      <div className="grid w-full grid-cols-1 gap-2 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5">
        {searchFilter && (
          <InputFilter
            accessorKey={searchFilter.accessorKey}
            debounce={300}
            defaultValue=""
            placeholder={searchFilter.placeholder}
            onChange={(value) => {
              if (searchFilter.onChangeHandler) {
                searchFilter.onChangeHandler(value ?? "")
              } else {
                table.getColumn(searchFilter.accessorKey)?.setFilterValue(value ?? undefined)
              }
            }}
          />
        )}
        {filtersDef.map((filter) => {
          if (isFilterHidden(filter)) return null

          if (filter.type === "text") {
            return (
              <InputFilter
                key={filter.accessorKey}
                accessorKey={filter.accessorKey}
                debounce={filter.debounce ?? 1000}
                defaultValue={filter.defaultValue}
                placeholder={filter.placeHolder}
                tooltip={filter.tooltip ?? filter.placeHolder}
                className="w-full truncate"
                onChange={(value) => {
                  if (filter.onChange) {
                    filter.onChange(value)
                  } else {
                    table.getColumn(filter.accessorKey)?.setFilterValue(value ?? undefined)
                  }
                }}
              />
            )
          }

          if (filter.type === "select") {
            return <SelectFilter key={filter.accessorKey} table={table} filter={filter} />
          }

          return (
            <DateFilter
              key={filter.accessorKey}
              filter={filter}
              defaultsRef={dateDefaultsRef}
              today={today}
            />
          )
        })}
        {(isTableFiltered || hasDefaultFilters) && (
          <Button
            variant="ghost"
            className="h-8 px-2 lg:px-3"
            onClick={() => {
              dateDefaultsRef.current = {}
              if (isTableFiltered) table.resetColumnFilters()
              resetFilters?.()
            }}
          >
            Reset
            <X data-icon="inline-end" />
          </Button>
        )}
      </div>
      <div className="flex items-center justify-end gap-2 self-end lg:self-start">
        {resolvedMultiRowActions.length > 0 &&
          table.getFilteredSelectedRowModel().rows.length > 0 && (
            <DataTableMultiRowActions
              rows={table.getFilteredSelectedRowModel().rows}
              actions={resolvedMultiRowActions}
            />
          )}
        {tableActions && <TableActionsMenu tableActions={tableActions} />}
        <DataTableViewOptions table={table} />
      </div>
    </div>
  )
}

